"""Citation-provider clients for the citation-explorer workflow.

Normal scorecard discovery uses only the GXL citation graph. Legacy
public-provider functions remain here for compatibility and focused tests.
"""

from __future__ import annotations

import json
import logging
import os
import random
import re
import time
import urllib.error
import urllib.parse
import urllib.request
from collections.abc import Callable
from concurrent.futures import ThreadPoolExecutor, as_completed
from dataclasses import asdict, dataclass, field
from datetime import UTC, datetime
from difflib import SequenceMatcher
from typing import Any

logger = logging.getLogger(__name__)

MAX_RETRIES = 5
BACKOFF_BASE_S = 1.0
BACKOFF_MAX_S = 30.0
DEFAULT_LIST_LIMIT = 50
MAX_LIST_RESULTS = 1_000
MAX_REACH_GROUPS = 5_000
REQUEST_TIMEOUT_S = 60
GXL_DISCOVERY_TARGET = 100
GXL_DISCOVERY_MULTIPLIER = 3
GXL_DISCOVERY_MAX = 300
GXL_YEAR_WORKERS = 6
GXL_MAX_EXACT_YEAR_SPAN = 15

_DOI_RE = re.compile(
    r"(?:doi\.org/|doi:\s*)?(10\.\d{4,9}/[-._;()/:A-Z0-9]+)",
    re.IGNORECASE,
)
_ARXIV_RE = re.compile(
    r"(?:arxiv\.org/(?:abs|pdf|html)/|arxiv[:./]|arx_|arxiv_)"
    r"(\d{4}\.\d{4,5})(?:v\d+)?"
    r"|^(\d{4}\.\d{4,5})(?:v\d+)?$",
    re.IGNORECASE,
)


def normalize_doi(value: str | None) -> str | None:
    """Normalize a DOI string. Return None when no DOI is present."""
    if not value:
        return None
    text = value.strip()
    match = _DOI_RE.search(text)
    if not match:
        # Bare DOI without prefix
        if text.lower().startswith("10."):
            doi = text.split()[0].rstrip(".,;)")
            return doi.lower()
        return None
    return match.group(1).rstrip(".,;)").lower()


def normalize_title(value: str | None) -> str:
    """Lowercase title with collapsed whitespace and stripped punctuation edges."""
    if not value:
        return ""
    cleaned = re.sub(r"\s+", " ", value.strip().lower())
    cleaned = cleaned.strip(" .,:;\"'`")
    return cleaned


def extract_arxiv_id(value: str | None) -> str | None:
    """Extract a bare arXiv id (``YYMM.NNNNN``) from a URL or id string."""
    if not value:
        return None
    match = _ARXIV_RE.search(value.strip())
    return next((group for group in match.groups() if group), None) if match else None


def user_agent() -> str:
    contact = os.getenv("CITATIONS_CONTACT_EMAIL", "dev@gxl.ai")
    return f"gxl-citation-explorer/0.1 (mailto:{contact})"


def get_json(url: str, *, headers: dict[str, str] | None = None) -> Any:
    """GET JSON with bounded retry/backoff for public provider APIs."""
    req_headers = {"Accept": "application/json", "User-Agent": user_agent()}
    if headers:
        req_headers.update(headers)
    request = urllib.request.Request(url, headers=req_headers)
    for attempt in range(MAX_RETRIES + 1):
        try:
            with urllib.request.urlopen(request, timeout=REQUEST_TIMEOUT_S) as response:
                return json.load(response)
        except urllib.error.HTTPError as exc:
            transient = exc.code in {408, 425, 429} or 500 <= exc.code < 600
            if not transient or attempt >= MAX_RETRIES:
                raise
            retry_after = exc.headers.get("Retry-After") if exc.headers else None
            try:
                delay = float(retry_after) if retry_after else None
            except (TypeError, ValueError):
                delay = None
            backoff = min(
                BACKOFF_MAX_S,
                delay if delay is not None else BACKOFF_BASE_S * (2**attempt),
            )
            wait = backoff + random.uniform(0, max(0.1, backoff * 0.2))
            logger.warning(
                "Provider request returned HTTP %d; retrying in %.2fs "
                "(attempt %d/%d): %s",
                exc.code,
                wait,
                attempt + 1,
                MAX_RETRIES,
                url,
            )
            time.sleep(wait)
        except (urllib.error.URLError, TimeoutError) as exc:
            if attempt >= MAX_RETRIES:
                raise
            backoff = min(BACKOFF_MAX_S, BACKOFF_BASE_S * (2**attempt))
            wait = backoff + random.uniform(0, max(0.1, backoff * 0.2))
            logger.warning(
                "Provider request failed; retrying in %.2fs (attempt %d/%d): %s",
                wait,
                attempt + 1,
                MAX_RETRIES,
                exc,
            )
            time.sleep(wait)
    raise RuntimeError("unreachable")


def _query(url: str, params: dict[str, Any]) -> str:
    return f"{url}?{urllib.parse.urlencode(params)}"


@dataclass
class CitingRecord:
    """One citing work before full-text validation."""

    title: str = ""
    paperclip_id: str | None = None
    doi: str | None = None
    pmid: str | None = None
    arxiv_id: str | None = None
    preprint_doi: str | None = None
    year: int | None = None
    citation_count: int | None = None
    openalex_id: str | None = None
    providers: list[str] = field(default_factory=list)
    source_ids: dict[str, str] = field(default_factory=dict)
    target_aliases: list[str] = field(default_factory=list)

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)


@dataclass
class ProviderChecks:
    """Independent count / provenance checks (not authoritative edge lists)."""

    crossref_is_referenced_by_count: int | None = None
    opencitations_citation_count: int | None = None
    openalex_cited_by_count: int | None = None
    icite_cited_by_pmid_count: int | None = None
    semantic_scholar_citation_count: int | None = None
    gxl_citation_count: int | None = None
    errors: dict[str, str] = field(default_factory=dict)

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)


@dataclass
class ProviderBundle:
    """Union of citing records plus independent checks for one target DOI."""

    target_doi: str
    target_pmid: str | None = None
    target_openalex_id: str | None = None
    target_title: str = ""
    target_summary: str = ""
    target_aliases: list[dict[str, str | None]] = field(default_factory=list)
    institution_count: int = 0
    discipline_count: int = 0
    top_disciplines: list[str] = field(default_factory=list)
    reach_complete: bool = False
    citation_counts_by_year: dict[int, int] = field(default_factory=dict)
    citing: list[CitingRecord] = field(default_factory=list)
    checks: ProviderChecks = field(default_factory=ProviderChecks)
    provider_edge_counts: dict[str, int] = field(default_factory=dict)
    errors: dict[str, str] = field(default_factory=dict)

    def to_dict(self) -> dict[str, Any]:
        return {
            "target_doi": self.target_doi,
            "target_pmid": self.target_pmid,
            "target_openalex_id": self.target_openalex_id,
            "target_title": self.target_title,
            "target_summary": self.target_summary,
            "target_aliases": list(self.target_aliases),
            "institution_count": self.institution_count,
            "discipline_count": self.discipline_count,
            "top_disciplines": list(self.top_disciplines),
            "reach_complete": self.reach_complete,
            "citation_counts_by_year": dict(self.citation_counts_by_year),
            "citing": [c.to_dict() for c in self.citing],
            "checks": self.checks.to_dict(),
            "provider_edge_counts": dict(self.provider_edge_counts),
            "errors": dict(self.errors),
        }


def resolve_pmid(doi: str) -> str | None:
    """Resolve a PubMed ID for a DOI via Europe PMC."""
    query = _query(
        "https://www.ebi.ac.uk/europepmc/webservices/rest/search",
        {"query": f"DOI:{doi}", "format": "json", "pageSize": 1},
    )
    result = get_json(query)
    rows = (result.get("resultList") or {}).get("result") or []
    if not rows:
        return None
    pmid = rows[0].get("pmid")
    return str(pmid) if pmid else None


def _fetch_openalex_groups(
    openalex_id: str,
    group_by: str,
    *,
    api_key: str | None,
) -> tuple[list[dict[str, Any]], bool]:
    """Fetch bounded grouped values for all works that cite one target."""
    groups: list[dict[str, Any]] = []
    cursor: str | None = "*"
    while cursor and len(groups) < MAX_REACH_GROUPS:
        params: dict[str, Any] = {
            "filter": f"cites:{openalex_id}",
            "group_by": group_by,
            "per-page": min(200, MAX_REACH_GROUPS - len(groups)),
            "cursor": cursor,
        }
        if api_key:
            params["api_key"] = api_key
        page = get_json(_query("https://api.openalex.org/works", params))
        batch = page.get("group_by") or []
        groups.extend(batch)
        cursor = (page.get("meta") or {}).get("next_cursor")
        if not batch:
            break
    return groups, not cursor


def _openalex_author_ids(work: dict[str, Any]) -> set[str]:
    return {
        str((authorship.get("author") or {}).get("id") or "")
        for authorship in work.get("authorships") or []
        if (authorship.get("author") or {}).get("id")
    }


def _find_openalex_aliases(
    target: dict[str, Any],
    *,
    api_key: str | None,
) -> list[dict[str, Any]]:
    """Find likely published/preprint versions using title, authors, and year."""
    title = str(target.get("title") or "").strip()
    target_id = str(target.get("id") or "")
    if not title or not target_id:
        return [target]
    params: dict[str, Any] = {
        "search": title,
        "per-page": 25,
        "select": (
            "id,doi,title,publication_year,ids,cited_by_count,"
            "authorships,locations"
        ),
    }
    if api_key:
        params["api_key"] = api_key
    candidates = get_json(_query("https://api.openalex.org/works", params)).get(
        "results"
    ) or []
    target_title = normalize_title(title)
    target_authors = _openalex_author_ids(target)
    target_year = int(target.get("publication_year") or 0)
    aliases = [target]
    seen = {target_id}
    for candidate in candidates:
        candidate_id = str(candidate.get("id") or "")
        if not candidate_id or candidate_id in seen:
            continue
        candidate_title = normalize_title(candidate.get("title") or "")
        if (
            SequenceMatcher(None, target_title, candidate_title).ratio()
            < 0.96
        ):
            continue
        candidate_authors = _openalex_author_ids(candidate)
        if (
            target_authors
            and candidate_authors
            and not target_authors.intersection(candidate_authors)
        ):
            continue
        candidate_year = int(candidate.get("publication_year") or 0)
        if target_year and candidate_year and abs(target_year - candidate_year) > 3:
            continue
        aliases.append(candidate)
        seen.add(candidate_id)
    return aliases


def _fetch_openalex_citing_works(
    openalex_id: str,
    *,
    list_limit: int,
    api_key: str | None,
) -> list[dict[str, Any]]:
    params: dict[str, Any] = {
        "filter": f"cites:{openalex_id}",
        "per-page": min(list_limit, 200),
        "select": (
            "id,doi,title,publication_year,ids,cited_by_count,"
            "authorships,primary_topic,locations"
        ),
    }
    if api_key:
        params["api_key"] = api_key
    results: list[dict[str, Any]] = []
    cursor: str | None = "*"
    while cursor and len(results) < list_limit:
        page_params = dict(params)
        page_params["cursor"] = cursor
        page_params["per-page"] = min(200, list_limit - len(results))
        page = get_json(_query("https://api.openalex.org/works", page_params))
        batch = page.get("results") or []
        results.extend(batch)
        cursor = (page.get("meta") or {}).get("next_cursor")
        if not batch:
            break
    return results[:list_limit]


def fetch_openalex(
    doi: str,
    *,
    list_limit: int,
    target_title: str = "",
) -> dict[str, Any]:
    """Fetch OpenAlex target metadata and a bounded citing-work list."""
    params: dict[str, Any] = {
        "select": (
            "id,doi,title,publication_year,ids,cited_by_count,"
            "referenced_works,updated_date,abstract_inverted_index,counts_by_year,"
            "authorships,locations"
        )
    }
    api_key = os.getenv("OPENALEX_API_KEY")
    if api_key:
        params["api_key"] = api_key
    try:
        target = get_json(
            _query(f"https://api.openalex.org/works/https://doi.org/{doi}", params)
        )
    except urllib.error.HTTPError as exc:
        if exc.code != 404 or not target_title:
            raise
        search_params = {
            **params,
            "search": target_title,
            "per-page": 10,
        }
        candidates = (
            get_json(_query("https://api.openalex.org/works", search_params)).get(
                "results"
            )
            or []
        )
        exact = [
            candidate
            for candidate in candidates
            if normalize_title(candidate.get("title") or "")
            == normalize_title(target_title)
        ]
        if not exact:
            raise
        target = max(
            exact,
            key=lambda candidate: int(candidate.get("cited_by_count") or 0),
        )
        logger.info(
            "Resolved OpenAlex target by exact title after DOI 404: %s",
            target.get("id"),
        )
    openalex_id = str(target["id"]).rsplit("/", 1)[-1]
    aliases = _find_openalex_aliases(target, api_key=api_key)
    target_aliases: list[dict[str, str | None]] = []
    results_by_key: dict[str, dict[str, Any]] = {}
    for alias in aliases:
        alias_id = str(alias.get("id") or "").rsplit("/", 1)[-1]
        alias_doi = normalize_doi(alias.get("doi") or (alias.get("ids") or {}).get("doi"))
        if not alias_id:
            continue
        target_aliases.append(
            {
                "openalex_id": alias_id,
                "doi": alias_doi,
                "title": str(alias.get("title") or ""),
            }
        )
        alias_label = f"openalex:{alias_id}"
        for work in _fetch_openalex_citing_works(
            alias_id,
            list_limit=list_limit,
            api_key=api_key,
        ):
            work_key = normalize_doi(work.get("doi")) or str(work.get("id") or "")
            existing = results_by_key.get(work_key)
            if existing is None:
                existing = dict(work)
                existing["_cited_target_aliases"] = [alias_label]
                results_by_key[work_key] = existing
            elif alias_label not in existing["_cited_target_aliases"]:
                existing["_cited_target_aliases"].append(alias_label)
    results = list(results_by_key.values())

    return {
        "target": target,
        "citing_works": results,
        "citing_count": len(results),
        "openalex_id": openalex_id,
        "target_aliases": target_aliases,
        "target_alias_dois": [
            alias["doi"] for alias in target_aliases if alias.get("doi")
        ],
        "institution_groups": [],
        "discipline_groups": [],
        "reach_complete": True,
    }


def abstract_from_inverted_index(value: Any) -> str:
    """Rebuild readable abstract text from an OpenAlex inverted index."""
    if not isinstance(value, dict):
        return ""
    positioned: list[tuple[int, str]] = []
    for word, positions in value.items():
        if not isinstance(positions, list):
            continue
        for position in positions:
            try:
                positioned.append((int(position), str(word)))
            except (TypeError, ValueError):
                continue
    positioned.sort(key=lambda item: item[0])
    return " ".join(word for _, word in positioned).strip()


def fetch_crossref(doi: str) -> dict[str, Any]:
    """Fetch Crossref target metadata (counts + outgoing refs; no citing list)."""
    contact = os.getenv("CITATIONS_CONTACT_EMAIL", "dev@gxl.ai")
    url = _query(
        f"https://api.crossref.org/works/{urllib.parse.quote(doi, safe='/')}",
        {"mailto": contact},
    )
    response = get_json(url)
    return {"target": response["message"]}


def fetch_icite(doi: str, *, list_limit: int, pmid: str | None = None) -> dict[str, Any]:
    """Fetch NIH iCite citing PMIDs for a DOI."""
    resolved = pmid or resolve_pmid(doi)
    if not resolved:
        return {"pmid": None, "target": None, "reason": "no PMID for DOI"}
    response = get_json(
        _query(
            "https://icite.od.nih.gov/api/pubs",
            {"pmids": resolved, "legacy": "false"},
        )
    )
    rows = response.get("data") or []
    target = rows[0] if rows else None
    if target:
        target = dict(target)
        for field_name in ("citedByPmids", "citedByPmidsByYear", "citedPmids"):
            values = target.get(field_name)
            if isinstance(values, list):
                target[field_name] = values[:list_limit]
    return {"pmid": resolved, "target": target}


def _json_object_from_output(output: str) -> dict[str, Any]:
    """Parse one JSON object from Paperclip command output."""
    text = (output or "").strip()
    try:
        value = json.loads(text)
    except json.JSONDecodeError:
        start = text.find("{")
        if start < 0:
            raise ValueError("citations returned no JSON object") from None
        value, _ = json.JSONDecoder().raw_decode(text[start:])
    if not isinstance(value, dict):
        raise ValueError("citations returned an unexpected JSON value")
    return value


def _citations_command_error(result: Any) -> str | None:
    """Return a failure message when the citations command did not succeed.

    ``/api/cli/execute`` often reports ``exit_code=0`` while embedding
    ``ERR: ... [exit 1]`` in stdout. Treat that as a failed lookup so the
    caller can retry the next identifier.
    """
    output = str(getattr(result, "output", "") or "")
    stderr = str(getattr(result, "stderr", "") or "")
    exit_code = int(getattr(result, "exit_code", 0) or 0)
    if exit_code != 0:
        return (stderr or output or "citations failed").strip()
    combined = f"{output}\n{stderr}"
    if "[exit 1]" in combined or output.lstrip().startswith("ERR:"):
        return (stderr or output or "citations failed").strip()
    return None


def _gxl_citation_identifiers(
    paperclip_id: str | None,
    doi: str | None,
) -> list[str]:
    """Paperclip ids to try against the GXL citation graph.

    ArXiv works are keyed as ``arx_YYMM.NNNNN``, not the DataCite DOI
    ``10.48550/arxiv....``. A truncated lookup id such as ``arx_2310`` is
    retried as the full dotted id derived from the DOI.
    """
    normalized_doi = normalize_doi(doi)
    arxiv_id = extract_arxiv_id(paperclip_id) or extract_arxiv_id(normalized_doi)
    candidates = [
        (paperclip_id or "").strip(),
        f"arx_{arxiv_id}" if arxiv_id else "",
        (normalized_doi or "").strip(),
    ]
    return list(dict.fromkeys(value for value in candidates if value))


def _fetch_gxl_citation_period(
    client: Any,
    identifier: str,
    period: tuple[str, int] | None,
    limit: int,
) -> dict[str, Any]:
    args = [
        identifier,
        "--in-corpus",
        "--sort",
        "citations",
        "-n",
        str(limit),
        "--json",
    ]
    if period is not None:
        option, value = period
        args[1:1] = [f"--{option}", str(value)]
    result = client.execute("citations", args, timeout=120)
    detail = _citations_command_error(result)
    if detail:
        raise RuntimeError(detail)
    return _json_object_from_output(getattr(result, "output", "") or "")


def fetch_gxl_citations(
    paperclip_id: str | None = None,
    doi: str | None = None,
    *,
    client: Any,
    target_year: int | None,
    list_limit: int,
) -> dict[str, Any]:
    """Fetch direct in-corpus citers from the current Paperclip VFS command.

    Exact-year queries prevent a graph sorted by date or impact from making the
    candidate pool newest-first. A failed Paperclip-id lookup is retried by DOI.
    """
    identifiers = _gxl_citation_identifiers(paperclip_id, doi)
    if not identifiers:
        raise ValueError("GXL citation discovery needs a Paperclip ID or DOI")

    current_year = datetime.now(UTC).year
    periods: list[tuple[str, int] | None]
    if target_year and 1800 <= int(target_year) <= current_year:
        first_year = int(target_year)
        exact_start = max(
            first_year,
            current_year - GXL_MAX_EXACT_YEAR_SPAN + 1,
        )
        periods = [
            ("year", year) for year in range(exact_start, current_year + 1)
        ]
        if exact_start > first_year:
            periods.insert(0, ("until", exact_start - 1))
    else:
        periods = [None]

    discovery_budget = min(
        GXL_DISCOVERY_MAX,
        max(GXL_DISCOVERY_TARGET, int(list_limit) * GXL_DISCOVERY_MULTIPLIER),
    )
    base_period_limit, extra_periods = divmod(discovery_budget, len(periods))
    period_limits = [
        base_period_limit + (1 if index < extra_periods else 0)
        for index in range(len(periods))
    ]

    last_errors: list[str] = []
    for identifier in identifiers:
        payloads: list[dict[str, Any]] = []
        errors: list[str] = []
        with ThreadPoolExecutor(
            max_workers=min(GXL_YEAR_WORKERS, max(1, len(periods)))
        ) as pool:
            futures = {
                pool.submit(
                    _fetch_gxl_citation_period,
                    client,
                    identifier,
                    period,
                    period_limits[index],
                ): period
                for index, period in enumerate(periods)
            }
            for future in as_completed(futures):
                try:
                    payloads.append(future.result())
                except Exception as exc:  # noqa: BLE001
                    errors.append(f"{futures[future]}: {exc}")
        if not payloads:
            last_errors = errors
            continue

        citing_by_id: dict[str, dict[str, Any]] = {}
        total: int | None = None
        target_title = ""
        for payload in payloads:
            if payload.get("citation_count") is not None:
                try:
                    total = max(total or 0, int(payload["citation_count"]))
                except (TypeError, ValueError):
                    pass
            if not target_title:
                target_title = str(payload.get("paper_title") or "")
            for row in payload.get("citing_papers") or []:
                path = str(row.get("path") or "").strip().rstrip("/")
                direct_id = path.rsplit("/", 1)[-1] if path else ""
                if not direct_id:
                    continue
                candidate = dict(row)
                candidate["paperclip_id"] = direct_id
                citing_by_id.setdefault(direct_id.lower(), candidate)
        return {
            "target": {
                "title": target_title,
                "citation_count": total,
                "identifier": identifier,
            },
            "citing_papers": list(citing_by_id.values()),
            "errors": errors,
        }

    raise RuntimeError("; ".join(last_errors) or "GXL citations lookup failed")


def fetch_semantic_scholar(
    doi: str,
    *,
    list_limit: int,
) -> dict[str, Any]:
    """Fetch alias-resolved citing works from Semantic Scholar."""
    api_key = os.getenv("SEMANTIC_SCHOLAR_API_KEY", "").strip()
    headers = {"x-api-key": api_key} if api_key else None
    arxiv_id = extract_arxiv_id(doi)
    identifier = f"ARXIV:{arxiv_id}" if arxiv_id else f"DOI:{doi}"
    paper_identifier = urllib.parse.quote(identifier, safe=":")
    citations: list[dict[str, Any]] = []
    offset = 0
    limit = max(1, min(int(list_limit), 9_999))
    citation_fields = "paperId,title,year,citationCount,externalIds"
    citation_count: int | None = None
    while len(citations) < limit:
        page_size = min(1_000, limit - len(citations))
        params = urllib.parse.urlencode(
            {
                "fields": citation_fields,
                "limit": page_size,
                "offset": offset,
            }
        )
        page = get_json(
            f"https://api.semanticscholar.org/graph/v1/paper/"
            f"{paper_identifier}/citations?{params}",
            headers=headers,
        )
        if citation_count is None and page.get("total") is not None:
            citation_count = int(page["total"])
        batch = [
            row.get("citingPaper") or {}
            for row in page.get("data") or []
            if row.get("citingPaper")
        ]
        citations.extend(batch)
        if len(batch) < page_size:
            break
        offset += len(batch)
    return {
        "target": {
            "citationCount": citation_count,
            "externalIds": {
                "DOI": doi,
                **({"ArXiv": arxiv_id} if arxiv_id else {}),
            },
        },
        "citations": citations[:limit],
    }


def fetch_opencitations(doi: str, *, list_limit: int) -> dict[str, Any]:
    """Fetch OpenCitations incoming citation edges (used as a check + edge source)."""
    encoded = urllib.parse.quote(f"doi:{doi}", safe=":/")
    citations = get_json(
        f"https://api.opencitations.net/index/v2/citations/{encoded}"
    )
    return {
        "citations": (citations or [])[:list_limit],
        "citation_count_returned": len(citations or []),
    }


def _ids_from_openalex(
    work: dict[str, Any],
) -> tuple[str | None, str | None, str | None, str | None]:
    ids = work.get("ids") or {}
    doi = normalize_doi(work.get("doi") or ids.get("doi"))
    pmid = None
    if ids.get("pmid"):
        pmid = str(ids["pmid"]).rsplit("/", 1)[-1]
    arxiv_id = None
    if ids.get("arxiv"):
        arxiv_id = extract_arxiv_id(str(ids["arxiv"]))
    preprint_doi = None
    for location in work.get("locations") or []:
        for field_name in ("landing_page_url", "pdf_url"):
            url = str(location.get(field_name) or "")
            if not arxiv_id and "arxiv.org" in url.lower():
                arxiv_id = extract_arxiv_id(url)
            candidate_doi = normalize_doi(url)
            if (
                candidate_doi
                and candidate_doi.startswith("10.1101/")
                and candidate_doi != doi
            ):
                preprint_doi = candidate_doi
    return doi, pmid, arxiv_id, preprint_doi


def _record_keys(
    paperclip_id: str | None,
    doi: str | None,
    pmid: str | None,
    arxiv_id: str | None,
    preprint_doi: str | None,
    title: str,
) -> list[str]:
    keys: list[str] = []
    if paperclip_id:
        keys.append(f"paperclip:{paperclip_id.lower()}")
    if doi:
        keys.append(f"doi:{doi}")
    if pmid:
        keys.append(f"pmid:{pmid}")
    if arxiv_id:
        keys.append(f"arxiv:{arxiv_id}")
    if preprint_doi:
        keys.append(f"doi:{preprint_doi}")
    title_key = normalize_title(title)
    if title_key:
        keys.append(f"title:{title_key}")
    return keys


def _is_preprint_doi(doi: str | None) -> bool:
    normalized = normalize_doi(doi) or ""
    return normalized.startswith(
        (
            "10.1101/",
            "10.21203/rs.",
            "10.2139/ssrn.",
            "10.48550/arxiv.",
        )
    )


def _merge_record(
    by_key: dict[str, CitingRecord],
    *,
    title: str,
    doi: str | None,
    pmid: str | None,
    arxiv_id: str | None,
    year: int | None,
    openalex_id: str | None,
    provider: str,
    paperclip_id: str | None = None,
    preprint_doi: str | None = None,
    target_aliases: list[str] | None = None,
    source_id: str | None = None,
    citation_count: int | None = None,
) -> None:
    keys = _record_keys(
        paperclip_id, doi, pmid, arxiv_id, preprint_doi, title
    )
    if not keys:
        return

    existing: CitingRecord | None = None
    for key in keys:
        hit = by_key.get(key)
        if hit is not None:
            existing = hit
            break

    if existing is None:
        record = CitingRecord(
            title=title or "",
            paperclip_id=paperclip_id,
            doi=doi,
            pmid=str(pmid) if pmid else None,
            arxiv_id=arxiv_id,
            preprint_doi=preprint_doi,
            year=year,
            citation_count=citation_count,
            openalex_id=openalex_id,
            providers=[provider],
            target_aliases=list(target_aliases or []),
        )
        if source_id:
            record.source_ids[provider] = source_id
        for key in keys:
            by_key[key] = record
        return

    if provider not in existing.providers:
        existing.providers.append(provider)
    if source_id:
        existing.source_ids[provider] = source_id
    for target_alias in target_aliases or []:
        if target_alias not in existing.target_aliases:
            existing.target_aliases.append(target_alias)
    promoted_to_published = bool(
        doi
        and existing.doi
        and _is_preprint_doi(existing.doi)
        and not _is_preprint_doi(doi)
    )
    if promoted_to_published:
        if not existing.preprint_doi:
            existing.preprint_doi = existing.doi
        existing.doi = doi
        existing.paperclip_id = paperclip_id
        existing.year = year if year is not None else existing.year
        existing.openalex_id = openalex_id or existing.openalex_id
    elif not existing.doi and doi:
        existing.doi = doi
    elif (
        doi
        and existing.doi
        and not _is_preprint_doi(existing.doi)
        and _is_preprint_doi(doi)
        and not existing.preprint_doi
    ):
        existing.preprint_doi = doi
    incoming_matches_canonical = not doi or doi == existing.doi
    if (
        not existing.paperclip_id
        and paperclip_id
        and incoming_matches_canonical
    ):
        existing.paperclip_id = paperclip_id
    if not existing.pmid and pmid:
        existing.pmid = str(pmid)
    if not existing.arxiv_id and arxiv_id:
        existing.arxiv_id = arxiv_id
    if not existing.preprint_doi and preprint_doi:
        existing.preprint_doi = preprint_doi
    if not existing.title and title:
        existing.title = title
    if existing.year is None and year is not None:
        existing.year = year
    if existing.citation_count is None and citation_count is not None:
        existing.citation_count = citation_count
    if not existing.openalex_id and openalex_id:
        existing.openalex_id = openalex_id

    # Keep every identifier key pointing at the same record.
    for key in _record_keys(
        existing.paperclip_id,
        existing.doi,
        existing.pmid,
        existing.arxiv_id,
        existing.preprint_doi,
        existing.title,
    ):
        by_key[key] = existing


def _opencitations_citing_doi(edge: dict[str, Any]) -> str | None:
    """Extract citing DOI from an OpenCitations citation edge."""
    for field_name in ("citing", "citing_doi"):
        raw = edge.get(field_name)
        if not raw:
            continue
        # Values look like "doi:10.1234/foo" or bare DOIs / OMIDs
        for part in str(raw).split():
            doi = normalize_doi(part.replace("doi:", ""))
            if doi:
                return doi
    return None


def _collect_legacy_providers(
    doi: str,
    *,
    list_limit: int = DEFAULT_LIST_LIMIT,
    fetchers: dict[str, Callable[..., dict[str, Any]]] | None = None,
    target_title: str = "",
) -> ProviderBundle:
    """Union citing records from OpenAlex, iCite, and Semantic Scholar.

    OpenCitations and Crossref provide independent count checks. Individual
    failures are isolated so the workflow can continue with partial results.
    """
    limit = max(1, min(int(list_limit), MAX_LIST_RESULTS))
    bundle = ProviderBundle(target_doi=doi)
    by_key: dict[str, CitingRecord] = {}
    target_alias_dois = [doi]
    institution_ids: set[str] = set()
    discipline_counts: dict[str, int] = {}

    def _openalex() -> dict[str, Any]:
        fn = (fetchers or {}).get("openalex")
        if fn:
            return fn(doi, list_limit=limit)
        return fetch_openalex(
            doi,
            list_limit=limit,
            target_title=target_title,
        )

    def _icite(
        target_doi: str = doi,
        pmid: str | None = None,
    ) -> dict[str, Any]:
        fn = (fetchers or {}).get("icite", fetch_icite)
        return fn(target_doi, list_limit=limit, pmid=pmid)

    def _crossref() -> dict[str, Any]:
        if doi.lower().startswith("10.48550/arxiv."):
            return {"target": {}}
        fn = (fetchers or {}).get("crossref", fetch_crossref)
        return fn(doi)

    def _opencitations(target_doi: str = doi) -> dict[str, Any]:
        fn = (fetchers or {}).get("opencitations", fetch_opencitations)
        return fn(target_doi, list_limit=limit)

    def _semantic_scholar() -> dict[str, Any]:
        fn = (fetchers or {}).get("semantic_scholar", fetch_semantic_scholar)
        return fn(doi, list_limit=limit)

    # OpenAlex first (gives title + OA id); others in parallel after.
    try:
        oa = _openalex()
        target = oa.get("target") or {}
        bundle.target_openalex_id = oa.get("openalex_id") or str(
            target.get("id", "")
        ).rsplit("/", 1)[-1]
        bundle.target_aliases = list(oa.get("target_aliases") or [])
        target_alias_dois = list(
            dict.fromkeys(
                [
                    doi,
                    *[
                        str(alias_doi)
                        for alias_doi in oa.get("target_alias_dois") or []
                        if alias_doi
                    ],
                ]
            )
        )
        bundle.target_title = target.get("title") or ""
        bundle.target_summary = abstract_from_inverted_index(
            target.get("abstract_inverted_index")
        )
        bundle.citation_counts_by_year = {
            int(row["year"]): int(row.get("cited_by_count") or 0)
            for row in (target.get("counts_by_year") or [])
            if row.get("year") is not None
        }
        bundle.checks.openalex_cited_by_count = target.get("cited_by_count")
        works = oa.get("citing_works") or []
        bundle.provider_edge_counts["openalex"] = len(works)
        for work in works:
            for authorship in work.get("authorships") or []:
                for institution in authorship.get("institutions") or []:
                    institution_id = str(
                        institution.get("id") or institution.get("display_name") or ""
                    ).strip()
                    if institution_id:
                        institution_ids.add(institution_id)
            topic = work.get("primary_topic") or {}
            field = topic.get("field") or {}
            discipline = str(field.get("display_name") or "").strip()
            if discipline:
                discipline_counts[discipline] = discipline_counts.get(discipline, 0) + 1
            wdoi, wpmid, warxiv, wpreprint_doi = _ids_from_openalex(work)
            oa_id = str(work.get("id", "")).rsplit("/", 1)[-1] or None
            year = work.get("publication_year")
            try:
                year_i = int(year) if year is not None else None
            except (TypeError, ValueError):
                year_i = None
            _merge_record(
                by_key,
                title=work.get("title") or "",
                doi=wdoi,
                pmid=wpmid,
                arxiv_id=warxiv,
                year=year_i,
                openalex_id=oa_id,
                provider="openalex",
                preprint_doi=wpreprint_doi,
                target_aliases=list(work.get("_cited_target_aliases") or []),
                source_id=oa_id,
            )
        bundle.institution_count = len(institution_ids)
        bundle.discipline_count = len(discipline_counts)
        bundle.top_disciplines = [
            name
            for name, _ in sorted(
                discipline_counts.items(),
                key=lambda item: (-item[1], item[0]),
            )[:4]
        ]
        institution_groups = oa.get("institution_groups") or []
        discipline_groups = oa.get("discipline_groups") or []
        if institution_groups:
            bundle.institution_count = len(institution_groups)
        if discipline_groups:
            bundle.discipline_count = len(discipline_groups)
            bundle.top_disciplines = [
                str(group.get("key_display_name") or "").strip()
                for group in sorted(
                    discipline_groups,
                    key=lambda group: -int(group.get("count") or 0),
                )[:4]
                if group.get("key_display_name")
            ]
        bundle.reach_complete = bool(oa.get("reach_complete"))
    except Exception as exc:  # noqa: BLE001 - isolate provider failures
        logger.warning("OpenAlex fetch failed for %s: %s", doi, exc)
        bundle.errors["openalex"] = str(exc)
        bundle.checks.errors["openalex"] = str(exc)

    # Resolve PMID once for iCite (and reuse Europe PMC result).
    try:
        bundle.target_pmid = resolve_pmid(doi)
    except Exception as exc:  # noqa: BLE001
        logger.warning("PMID resolve failed for %s: %s", doi, exc)
        bundle.errors["europepmc"] = str(exc)

    with ThreadPoolExecutor(max_workers=4) as pool:
        futures = {
            pool.submit(_icite, doi, bundle.target_pmid): "icite",
            pool.submit(_crossref): "crossref",
            pool.submit(_opencitations, doi): "opencitations",
            pool.submit(_semantic_scholar): "semantic_scholar",
        }
        results: dict[str, Any] = {}
        for fut in as_completed(futures):
            name = futures[fut]
            try:
                results[name] = fut.result()
            except Exception as exc:  # noqa: BLE001
                logger.warning("%s fetch failed for %s: %s", name, doi, exc)
                bundle.errors[name] = str(exc)
                bundle.checks.errors[name] = str(exc)

    icite = results.get("icite")
    if icite:
        if icite.get("pmid") and not bundle.target_pmid:
            bundle.target_pmid = str(icite["pmid"])
        target = icite.get("target")
        if target:
            bundle.checks.icite_cited_by_pmid_count = target.get("citation_count") or target.get(
                "citedByPmidCount"
            )
            cited = target.get("citedByPmids") or []
            bundle.provider_edge_counts["icite"] = len(cited)
            for pmid in cited:
                _merge_record(
                    by_key,
                    title="",
                    doi=None,
                    pmid=str(pmid),
                    arxiv_id=None,
                    year=None,
                    openalex_id=None,
                    provider="icite",
                    target_aliases=[f"doi:{doi}"],
                    source_id=str(pmid),
                )

    semantic_scholar = results.get("semantic_scholar")
    if semantic_scholar:
        semantic_target = semantic_scholar.get("target") or {}
        bundle.checks.semantic_scholar_citation_count = semantic_target.get(
            "citationCount"
        )
        semantic_paper_id = str(semantic_target.get("paperId") or "")
        semantic_alias = (
            f"semantic_scholar:{semantic_paper_id}"
            if semantic_paper_id
            else f"semantic_scholar:doi:{doi}"
        )
        citations = semantic_scholar.get("citations") or []
        bundle.provider_edge_counts["semantic_scholar"] = len(citations)
        external_ids = semantic_target.get("externalIds") or {}
        semantic_doi = normalize_doi(external_ids.get("DOI"))
        if semantic_paper_id and not any(
            alias.get("semantic_scholar_id") == semantic_paper_id
            for alias in bundle.target_aliases
        ):
            bundle.target_aliases.append(
                {
                    "semantic_scholar_id": semantic_paper_id,
                    "doi": semantic_doi,
                    "arxiv_id": extract_arxiv_id(external_ids.get("ArXiv")),
                    "title": str(semantic_target.get("title") or ""),
                }
            )
        for work in citations:
            ids = work.get("externalIds") or {}
            work_doi = normalize_doi(ids.get("DOI"))
            work_pmid = str(ids.get("PubMed") or "") or None
            work_arxiv = extract_arxiv_id(ids.get("ArXiv"))
            paper_id = str(work.get("paperId") or "") or None
            year = work.get("year")
            try:
                year_i = int(year) if year is not None else None
            except (TypeError, ValueError):
                year_i = None
            _merge_record(
                by_key,
                title=str(work.get("title") or ""),
                doi=work_doi,
                pmid=work_pmid,
                arxiv_id=work_arxiv,
                year=year_i,
                openalex_id=None,
                provider="semantic_scholar",
                target_aliases=[semantic_alias],
                source_id=paper_id,
            )

    crossref = results.get("crossref")
    if crossref:
        msg = crossref.get("target") or {}
        bundle.checks.crossref_is_referenced_by_count = msg.get("is-referenced-by-count")
        if not bundle.target_title:
            titles = msg.get("title") or []
            if titles:
                bundle.target_title = titles[0]

    oc = results.get("opencitations")
    if oc:
        citations = oc.get("citations") or []
        bundle.checks.opencitations_citation_count = oc.get("citation_count_returned")
        # OpenCitations edges are useful when OpenAlex is thin; keep as edges
        # but still surface the count under checks.
        bundle.provider_edge_counts["opencitations"] = len(citations)
        for edge in citations:
            citing_doi = _opencitations_citing_doi(edge)
            if not citing_doi:
                continue
            _merge_record(
                by_key,
                title="",
                doi=citing_doi,
                pmid=None,
                arxiv_id=None,
                year=None,
                openalex_id=None,
                provider="opencitations",
                target_aliases=[f"doi:{doi}"],
                source_id=str(edge.get("oci") or citing_doi),
            )

    # Published and preprint aliases can have disjoint citation graphs.
    # OpenAlex alias edges are already merged above; add DOI-based iCite and
    # OpenCitations edges for every alternate DOI as well.
    for alias_doi in target_alias_dois[1:]:
        alias_results: dict[str, Any] = {}
        with ThreadPoolExecutor(max_workers=2) as pool:
            futures = {
                pool.submit(_icite, alias_doi, None): "icite",
                pool.submit(_opencitations, alias_doi): "opencitations",
            }
            for future in as_completed(futures):
                provider = futures[future]
                try:
                    alias_results[provider] = future.result()
                except Exception as exc:  # noqa: BLE001
                    logger.warning(
                        "%s alias fetch failed for %s: %s",
                        provider,
                        alias_doi,
                        exc,
                    )
        icite_alias = alias_results.get("icite") or {}
        icite_target = icite_alias.get("target") or {}
        cited_pmids = icite_target.get("citedByPmids") or []
        bundle.provider_edge_counts["icite"] = (
            bundle.provider_edge_counts.get("icite", 0) + len(cited_pmids)
        )
        for cited_pmid in cited_pmids:
            _merge_record(
                by_key,
                title="",
                doi=None,
                pmid=str(cited_pmid),
                arxiv_id=None,
                year=None,
                openalex_id=None,
                provider="icite",
                target_aliases=[f"doi:{alias_doi}"],
                source_id=str(cited_pmid),
            )
        oc_alias = alias_results.get("opencitations") or {}
        citations = oc_alias.get("citations") or []
        bundle.provider_edge_counts["opencitations"] = (
            bundle.provider_edge_counts.get("opencitations", 0) + len(citations)
        )
        for edge in citations:
            citing_doi = _opencitations_citing_doi(edge)
            if not citing_doi:
                continue
            _merge_record(
                by_key,
                title="",
                doi=citing_doi,
                pmid=None,
                arxiv_id=None,
                year=None,
                openalex_id=None,
                provider="opencitations",
                target_aliases=[f"doi:{alias_doi}"],
                source_id=str(edge.get("oci") or citing_doi),
            )

    # by_key stores multiple aliases per record; unique by identity.
    unique: list[CitingRecord] = []
    seen: set[int] = set()
    for record in by_key.values():
        marker = id(record)
        if marker in seen:
            continue
        seen.add(marker)
        unique.append(record)
    bundle.citing = unique
    return bundle


def collect_providers(
    doi: str,
    *,
    list_limit: int = DEFAULT_LIST_LIMIT,
    fetchers: dict[str, Callable[..., dict[str, Any]]] | None = None,
    target_title: str = "",
    paperclip_id: str | None = None,
    target_year: int | None = None,
    target_versions: list[dict[str, Any]] | None = None,
    client: Any = None,
) -> ProviderBundle:
    """Collect direct in-corpus GXL citers for the first matching stage."""
    limit = max(1, min(int(list_limit), MAX_LIST_RESULTS))
    bundle = ProviderBundle(target_doi=doi)
    by_key: dict[str, CitingRecord] = {}

    gxl_fetcher = (fetchers or {}).get("gxl", fetch_gxl_citations)
    versions = [
        {
            "paperclip_id": paperclip_id,
            "doi": doi or None,
            "year": target_year,
        },
        *(target_versions or []),
    ]
    seen_versions: set[tuple[str, str]] = set()
    successful_versions = 0
    version_errors: list[str] = []
    for version in versions:
        version_id = str(version.get("paperclip_id") or "").strip()
        version_doi = normalize_doi(version.get("doi"))
        version_key = (version_id.lower(), version_doi or "")
        if version_key in seen_versions:
            continue
        seen_versions.add(version_key)
        try:
            gxl = gxl_fetcher(
                version_id or None,
                version_doi,
                client=client,
                target_year=version.get("year"),
                list_limit=limit,
            )
        except Exception as exc:  # noqa: BLE001
            version_errors.append(f"{version_doi or version_id}: {exc}")
            continue
        successful_versions += 1
        target = gxl.get("target") or {}
        if not bundle.target_title:
            bundle.target_title = str(target.get("title") or target_title or "")
        if target.get("citation_count") is not None:
            citation_count = int(target["citation_count"])
            bundle.checks.gxl_citation_count = max(
                bundle.checks.gxl_citation_count or 0,
                citation_count,
            )
        for row in gxl.get("citing_papers") or []:
            path = str(row.get("path") or "").strip().rstrip("/")
            direct_id = str(row.get("paperclip_id") or "")
            if not direct_id and path:
                direct_id = path.rsplit("/", 1)[-1]
            if not direct_id:
                continue
            year = row.get("year")
            citations = row.get("citations")
            try:
                year_i = int(year) if year is not None else None
            except (TypeError, ValueError):
                year_i = None
            try:
                citations_i = int(citations) if citations is not None else None
            except (TypeError, ValueError):
                citations_i = None
            _merge_record(
                by_key,
                title=str(row.get("title") or ""),
                paperclip_id=direct_id,
                doi=normalize_doi(row.get("doi")),
                pmid=str(row.get("pmid") or "") or None,
                arxiv_id=(
                    direct_id.removeprefix("arx_")
                    if direct_id.startswith("arx_")
                    else None
                ),
                year=year_i,
                citation_count=citations_i,
                openalex_id=None,
                provider="gxl",
                target_aliases=[
                    f"gxl:{target.get('identifier') or version_id or version_doi}"
                ],
                source_id=direct_id,
            )
    if not successful_versions:
        detail = "; ".join(version_errors) or "GXL citations lookup failed"
        logger.warning("GXL citation fetch failed for %s: %s", doi, detail)
        bundle.errors["gxl"] = detail
        bundle.checks.errors["gxl"] = detail

    unique: list[CitingRecord] = []
    seen: set[int] = set()
    for record in by_key.values():
        marker = id(record)
        if marker not in seen:
            seen.add(marker)
            unique.append(record)
    bundle.citing = unique
    bundle.provider_edge_counts["gxl"] = len(unique)
    if version_errors and successful_versions:
        bundle.errors["gxl_partial"] = "; ".join(version_errors)
        bundle.checks.errors["gxl_partial"] = "; ".join(version_errors)
    return bundle


def collect_semantic_scholar(
    bundle: ProviderBundle,
    doi: str,
    *,
    list_limit: int,
    fetchers: dict[str, Callable[..., dict[str, Any]]] | None = None,
) -> list[CitingRecord]:
    """Add a bounded S2 fallback to an existing GXL provider bundle.

    The returned list contains only records that were not already represented
    in the GXL set. Existing GXL records can still gain S2 provenance.
    """
    if not doi or list_limit <= 0:
        return []

    by_key: dict[str, CitingRecord] = {}
    existing_ids = {id(record) for record in bundle.citing}
    for record in bundle.citing:
        for key in _record_keys(
            record.paperclip_id,
            record.doi,
            record.pmid,
            record.arxiv_id,
            record.preprint_doi,
            record.title,
        ):
            by_key[key] = record

    semantic_fetcher = (fetchers or {}).get(
        "semantic_scholar", fetch_semantic_scholar
    )
    try:
        semantic = semantic_fetcher(doi, list_limit=list_limit)
        semantic_target = semantic.get("target") or {}
        if semantic_target.get("citationCount") is not None:
            bundle.checks.semantic_scholar_citation_count = int(
                semantic_target["citationCount"]
            )
        citations = semantic.get("citations") or []
        bundle.provider_edge_counts["semantic_scholar"] = len(citations)
        semantic_id = str(semantic_target.get("paperId") or "")
        target_alias = (
            f"semantic_scholar:{semantic_id}"
            if semantic_id
            else f"semantic_scholar:doi:{doi}"
        )
        for work in citations:
            ids = work.get("externalIds") or {}
            year = work.get("year")
            citer_count = work.get("citationCount")
            try:
                year_i = int(year) if year is not None else None
            except (TypeError, ValueError):
                year_i = None
            try:
                citer_count_i = (
                    int(citer_count) if citer_count is not None else None
                )
            except (TypeError, ValueError):
                citer_count_i = None
            paper_id = str(work.get("paperId") or "") or None
            _merge_record(
                by_key,
                title=str(work.get("title") or ""),
                doi=normalize_doi(ids.get("DOI")),
                pmid=str(ids.get("PubMed") or "") or None,
                arxiv_id=extract_arxiv_id(ids.get("ArXiv")),
                year=year_i,
                citation_count=citer_count_i,
                openalex_id=None,
                provider="semantic_scholar",
                target_aliases=[target_alias],
                source_id=paper_id,
            )
    except Exception as exc:  # noqa: BLE001
        logger.warning("Semantic Scholar fetch failed for %s: %s", doi, exc)
        bundle.errors["semantic_scholar"] = str(exc)
        bundle.checks.errors["semantic_scholar"] = str(exc)
        return []

    unique: list[CitingRecord] = []
    seen: set[int] = set()
    for record in by_key.values():
        marker = id(record)
        if marker not in seen:
            seen.add(marker)
            unique.append(record)
    bundle.citing = unique
    return [record for record in unique if id(record) not in existing_ids]
